import React from 'react';
import DashboardChart from './DashboardChart';
import CalendarWidget from './CalendarWidget';

const SupervisorReports = ({ properties, clients, adminInfo }) => {
  // --- منطق لوحة التحكم (منقول من Dashboard.js) ---
  const totalProperties = properties.length;
  const totalClients = clients.length;
  const forSale = properties.filter(p => p.status === 'ترم أول').length;
  const forRent = properties.filter(p => p.status === 'ترم ثاني').length;
  
  const totalValue = properties.reduce((acc, curr) => acc + (Number(curr.price) || 0), 0);
  const avgPrice = totalProperties > 0 ? totalValue / totalProperties : 0;

  const availableCount = properties.filter(p => p.availability === 'متاحة').length;
  const unavailableCount = totalProperties - availableCount;

  const priceRanges = {
    'أقل من 500 ألف': 0,
    '500 ألف - مليون': 0,
    'مليون - 3 مليون': 0,
    '3 مليون - 5 مليون': 0,
    'أكثر من 5 مليون': 0,
  };
  properties.forEach(p => {
    const price = p.price || 0;
    if (price < 500000) priceRanges['أقل من 500 ألف']++;
    else if (price <= 1000000) priceRanges['500 ألف - مليون']++;
    else if (price <= 3000000) priceRanges['مليون - 3 مليون']++;
    else if (price <= 5000000) priceRanges['3 مليون - 5 مليون']++;
    else priceRanges['أكثر من 5 مليون']++;
  });

  const budgetRanges = {
    'أقل من 500 ألف': 0,
    '500 ألف - مليون': 0,
    'مليون - 3 مليون': 0,
    'أكثر من 3 مليون': 0,
  };
  clients.forEach(c => {
    const budget = c.budget || 0;
    if (budget < 500000) budgetRanges['أقل من 500 ألف']++;
    else if (budget <= 1000000) budgetRanges['500 ألف - مليون']++;
    else if (budget <= 3000000) budgetRanges['مليون - 3 مليون']++;
    else budgetRanges['أكثر من 3 مليون']++;
  });

  const typeCounts = properties.reduce((acc, curr) => {
    const t = curr.type || 'غير محدد';
    acc[t] = (acc[t] || 0) + 1;
    return acc;
  }, {});

  const propertiesByCity = properties.reduce((acc, curr) => {
    const city = curr.location?.city || 'غير محدد';
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.entries(propertiesByCity).map(([label, value]) => ({ label, value })).sort((a, b) => b.value - a.value).slice(0, 5);

  const clientLocationCounts = clients.reduce((acc, curr) => {
    const loc = curr.preferredLocation || 'غير محدد';
    acc[loc] = (acc[loc] || 0) + 1;
    return acc;
  }, {});
  const clientLocationChartData = Object.entries(clientLocationCounts)
    .map(([label, value]) => ({ label, value }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);

  const today = new Date();
  const y = today.getFullYear();
  const m = String(today.getMonth() + 1).padStart(2, '0');
  const calendarEvents = [
    { date: `${y}-${m}-05`, title: 'تسليم ملازم الفيزياء', time: '09:00 ص' },
    { date: `${y}-${m}-12`, title: 'وصول كتب المراجعة', time: '01:00 م' },
    { date: `${y}-${m}-20`, title: 'شحن طلبيات الصعيد', time: '11:00 ص' },
    { date: `${y}-${m}-25`, title: 'جرد المخزن الشهري', time: '04:00 م' },
  ];

  const topAgents = properties.reduce((acc, p) => {
      acc[p.ownerName] = (acc[p.ownerName] || 0) + 1;
      return acc;
  }, {});
  const sortedAgents = Object.entries(topAgents).sort(([,a],[,b]) => b-a).slice(0, 3);

  // --- منطق التقارير (المبيعات) ---
  const soldProperties = properties.filter(p => {
    const isSold = p.availability === 'مباعة';
    if (adminInfo?.role === 'supervisor') {
      return isSold && p.addedBy === adminInfo.username;
    }
    return isSold;
  });
  
  const totalRevenue = soldProperties.reduce((acc, curr) => acc + (Number(curr.price) || 0), 0);
  const totalSales = soldProperties.length;

  // تجهيز بيانات الرسم البياني: المبيعات حسب المدينة
  const salesByCity = soldProperties.reduce((acc, curr) => {
    const city = curr.location?.city || 'غير محدد';
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});
  
  const salesChartData = Object.entries(salesByCity).map(([label, value]) => ({ label, value }));

  return (
    <div className="container fade-in">
      <h2 className="mb-4">📊 لوحة التحكم والتقارير - {adminInfo?.name || 'المسؤول'}</h2>
      
      {/* --- إحصائيات عامة --- */}
      <div className="row mb-4">
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-primary shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي الكتب/الملازم</h5>
              <p className="card-text display-4">{totalProperties}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-success shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">إجمالي الطلاب</h5>
              <p className="card-text display-4">{totalClients}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-info shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">المبيعات المحققة</h5>
              <p className="card-text display-6">{totalSales}</p>
              <p className="card-text display-4">{totalSales}</p>
            </div>
          </div>
        </div>
        <div className="col-md-3 mb-3">
          <div className="card text-white bg-warning shadow-sm h-100">
            <div className="card-body">
              <h5 className="card-title">الإيرادات</h5>
              <p className="card-text fs-4">{totalRevenue.toLocaleString()} ج</p>
            </div>
          </div>
        </div>
      </div>

      {/* --- الرسوم البيانية --- */}
      <div className="row mb-4">
        <div className="col-md-6 mb-4">
            <DashboardChart data={chartData} title="📊 الكتب حسب المادة/القسم" />
        </div>
        <div className="col-md-6 mb-4">
            <DashboardChart data={clientLocationChartData} title="📍 الصفوف الأكثر طلباً" />
        </div>
      </div>

      <div className="row">
        <div className="col-md-8 mb-4">
           <div className="card shadow-sm h-100">
             <div className="card-header bg-light fw-bold">📋 سجل المبيعات الأخيرة</div>
             <div className="card-body p-0">
               <div className="table-responsive">
                 <table className="table table-hover mb-0 align-middle">
                   <thead className="table-light">
                     <tr>
                       <th>الكتاب</th>
                       <th>المادة</th>
                       <th>السعر</th>
                       <th>الحالة</th>
                       {adminInfo?.role === 'admin' && <th>تمت الإضافة بواسطة</th>}
                     </tr>
                   </thead>
                   <tbody>
                     {soldProperties.length > 0 ? soldProperties.map(p => (
                       <tr key={p.id}>
                         <td>{p.type}</td>
                         <td>{p.location?.neighborhood}</td>
                         <td className="text-success fw-bold">{p.price?.toLocaleString()} ج</td>
                         <td><span className="badge bg-success">تم البيع</span></td>
                         {adminInfo?.role === 'admin' && <td><span className="badge bg-secondary">{p.addedBy || 'غير معروف'}</span></td>}
                       </tr>
                     )) : (
                       <tr><td colSpan={adminInfo?.role === 'admin' ? "5" : "4"} className="text-center py-4 text-muted">لا توجد مبيعات مسجلة بعد</td></tr>
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           </div>
        </div>
        
        <div className="col-md-4 mb-4">
            <div className="card shadow-sm h-100">
                <div className="card-header bg-light fw-bold">🏆 أفضل المدرسين/المكتبات</div>
                <ul className="list-group list-group-flush">
                    {sortedAgents.map(([name, count], index) => (
                        <li key={name} className="list-group-item d-flex align-items-center">
                            <span className="fs-4 me-3">{['🥇', '🥈', '🥉'][index]}</span>
                            <div>
                                <h6 className="mb-0">{name}</h6>
                                <small className="text-muted">أضاف {count} كتاب</small>
                            </div>
                        </li>
                    ))}
                </ul>
            </div>
        </div>

        <div className="col-12 mb-4">
            <CalendarWidget events={calendarEvents} />
        </div>
      </div>
    </div>
  );
};

export default SupervisorReports;
